-- Sources : séries internationales PokéCardex https://www.pokecardex.com/series ; noms et codes recoupés auprès de PokéCardex et de listes de séries publiques.
-- NOTE : une série de CARTES n'implique pas l'existence de tous les produits scellés.
-- Dates renseignées uniquement lorsqu'elles sont vérifiées. Les séries historiques conservent une date nulle.
ON CONFLICT (id) DO UPDATE SET block_name=excluded.block_name,set_code=excluded.set_code,release_date=COALESCE(excluded.release_date,public.catalog_series.release_date),display_order=excluded.display_order,color=excluded.color,source_url=excluded.source_url;
